'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );
var smallX = require( './fixtures/julia/small_x.json' );
var largeX = require( './fixtures/julia/large_x.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a function', function test( t ) {
	var logcdf = factory( 0.0, 1.0 );
	t.strictEqual( typeof logcdf, 'function', 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the created function returns `NaN`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 1.0, 1.0 );
	y = logcdf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NaN, 1.0 );
	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( 1.0, NaN );
	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NaN, NaN );
	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NaN, NaN );
	y = logcdf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a finite `a` and `b`, the function returns a function which returns `0` when provided a number greater than or equal to one for `x`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 0.5, 1.0 );
	y = logcdf( PINF );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = logcdf( 100.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = logcdf( 10.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = logcdf( 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	t.end();
});

tape( 'if provided a finite `a` and `b`, the function returns a function which returns `-infinity` when provided a number smaller than or equal to zero for `x`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 0.5, 1.0 );
	y = logcdf( NINF );
	t.strictEqual( y, NINF, 'returns expected value' );

	y = logcdf( -100.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	y = logcdf( -10.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	y = logcdf( -1.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	y = logcdf( 0.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `b`, the created function always returns `NaN`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 1.0, 0.0 );

	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( 1.0, -1.0 );

	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( 1.0, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( PINF, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NaN, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `a`, the created function always returns `NaN`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 0.0, 0.5 );

	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( -1.0, 0.5 );

	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, 1.0 );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, PINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, NaN );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the created function evaluates the logcdf for random `x`, `a` and `b`', function test( t ) {
	var expected;
	var logcdf;
	var a;
	var b;
	var i;
	var x;
	var y;

	expected = data.expected;
	x = data.x;
	a = data.a;
	b = data.b;
	for ( i = 0; i < expected.length; i++ ) {
		logcdf = factory( a[i], b[i] );
		y = logcdf( x[i] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 25 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the created function evaluates the logcdf for small `x`', function test( t ) {
	var expected;
	var logcdf;
	var a;
	var b;
	var i;
	var x;
	var y;

	expected = smallX.expected;
	x = smallX.x;
	a = smallX.a;
	b = smallX.b;
	for ( i = 0; i < expected.length; i++ ) {
		logcdf = factory( a[i], b[i] );
		y = logcdf( x[i] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the created function evaluates the logcdf for `x` close to `1`', function test( t ) {
	var expected;
	var logcdf;
	var a;
	var b;
	var i;
	var x;
	var y;

	expected = largeX.expected;
	x = largeX.x;
	a = largeX.a;
	b = largeX.b;
	for ( i = 0; i < expected.length; i++ ) {
		logcdf = factory( a[i], b[i] );
		y = logcdf( x[i] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 148 ), true, 'returns expected value' );
	}
	t.end();
});
